namespace Pharos.Server.Result.Domain;

/// <summary>
/// Represents the final result for a test order, calculated across all replicates.
/// </summary>
public abstract class GroupTestResult : TestResult
{
    /// <summary>
    /// Group ID is generated by the instrument for calibrators and curve controls.
    /// All replicates in a calibrator (curve control share the same group ID).
    /// </summary>
    public Guid GroupId { get; set; }

    /// <summary>
    /// The planned number of the test results in the group (e.g. the number of calibrator points).
    /// </summary>
    public int GroupSize { get; set; } = 1;
}
